class Solution {
    public ListNode partition(ListNode head, int x) {
        ListNode beforeHead = new ListNode(0);
        ListNode afterHead = new ListNode(0);
        ListNode before = beforeHead;
        ListNode after = afterHead;

        while (head != null) {
            if (head.val < x) {
                before.next = head;
                before = before.next;
            } else {
                after.next = head;
                after = after.next;
            }
            head = head.next;
        }

        after.next = null;
        before.next = afterHead.next;
        return beforeHead.next;
    }
}

class Solution {
    public ListNode partition(ListNode head, int x) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        ListNode lastSmall = dummy;
        while (lastSmall.next != null && lastSmall.next.val < x) {
            lastSmall = lastSmall.next;
        }

        ListNode prev = lastSmall;
        while (prev.next != null) {
            if (prev.next.val < x) {
                ListNode node = prev.next;
                prev.next = node.next;
                node.next = lastSmall.next;
                lastSmall.next = node;
                lastSmall = node;
            } else {
                prev = prev.next;
            }
        }
        return dummy.next;
    }
}

class Solution {
    public ListNode partition(ListNode head, int x) {
        Parts parts = build(head, x);
        if (parts.beforeHead == null) return parts.afterHead;
        parts.beforeTail.next = parts.afterHead;
        return parts.beforeHead;
    }

    private Parts build(ListNode node, int x) {
        if (node == null) return new Parts();
        ListNode next = node.next;
        node.next = null;
        Parts rest = build(next, x);

        if (node.val < x) {
            node.next = rest.beforeHead;
            rest.beforeHead = node;
            if (rest.beforeTail == null) rest.beforeTail = node;
        } else {
            node.next = rest.afterHead;
            rest.afterHead = node;
            if (rest.afterTail == null) rest.afterTail = node;
        }
        return rest;
    }

    private static class Parts {
        ListNode beforeHead;
        ListNode beforeTail;
        ListNode afterHead;
        ListNode afterTail;
    }
}

import java.util.*;

class Solution {
    public ListNode partition(ListNode head, int x) {
        List<ListNode> before = new ArrayList<>();
        List<ListNode> after = new ArrayList<>();

        while (head != null) {
            ListNode next = head.next;
            head.next = null;
            if (head.val < x) {
                before.add(head);
            } else {
                after.add(head);
            }
            head = next;
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (ListNode node : before) {
            tail.next = node;
            tail = tail.next;
        }
        for (ListNode node : after) {
            tail.next = node;
            tail = tail.next;
        }
        tail.next = null;
        return dummy.next;
    }
}
